INSERT INTO ui.dashboardquery (idashboardqueryid, bparametersrequired, vcfilterparametersjson, vcdashboardquery, formattingrequiered, runonanalytics, transposerequired) VALUES (58, true, '{"Party": null, "Address": null}', '{
    "Account":"WITH profile AS (SELECT * FROM profiles.account pv left join masters.accounts v on v.iaccountid = pv.iaccountid where v.vcexternalaccountid = :Address  order by tdate desc limit 1) SELECT X.* FROM (VALUES (''Days In System'',(select CASE WHEN  cast(val->''daysInTheSystem''->>''payer'' as int) IS NOT NULL and cast(val->''daysInTheSystem''->>''payee'' as int) IS NOT NULL THEN CASE WHEN cast(val->''daysInTheSystem''->>''payer'' as int) > cast(val->''daysInTheSystem''->>''payee'' as int) THEN val->''daysInTheSystem''->>''payer'' else val->''daysInTheSystem''->>''payee'' END WHEN cast(val->''daysInTheSystem''->>''payer'' as int) IS NOT NULL THEN val->''daysInTheSystem''->>''payer'' else val->''daysInTheSystem''->>''payee''  END from profile)), (''Total Value As Payer'',(SELECT val->''totalValue''->>''payer'' FROM profile)), (''Average Value As Payer'',(SELECT val->''avgValue''->''p90d''->>''payer'' FROM profile)), (''Total Value As Payee'',(SELECT val->''totalValue''->>''payee'' FROM profile)), (''Average Value As Payee'',(SELECT val->''avgValue''->''p90d''->>''payee'' FROM profile)) ) AS X (\"name\",\"value\");",
    "VPA": "WITH profile AS (SELECT *  FROM profiles.vpa pv left join masters.vpa v on v.ivpaid = pv.ivpaid where v.vcexternaladdressid = :Address order by tdate desc limit 1) SELECT X.* FROM (VALUES (''Days In System'',(select CASE WHEN  cast(val->''daysInTheSystem''->>''payer'' as int) IS NOT NULL and cast(val->''daysInTheSystem''->>''payee'' as int) IS NOT NULL THEN CASE WHEN cast(val->''daysInTheSystem''->>''payer'' as int) > cast(val->''daysInTheSystem''->>''payee'' as int) THEN val->''daysInTheSystem''->>''payer'' else val->''daysInTheSystem''->>''payee'' END WHEN cast(val->''daysInTheSystem''->>''payer'' as int) IS NOT NULL THEN val->''daysInTheSystem''->>''payer'' else val->''daysInTheSystem''->>''payee''  END from profile)), (''Total Value As Payer'',(SELECT val->''totalValue''->>''payer'' FROM profile)), (''Average Value As Payer'',(SELECT val->''avgValue''->''p90d''->>''payer'' FROM profile)), (''Total Value As Payee'',(SELECT val->''totalValue''->>''payee'' FROM profile)), (''Average Value As Payee'',(SELECT val->''avgValue''->''p90d''->>''payee'' FROM profile)) ) AS X (\"name\", \"value\");"
}', false, true, false);

